-- supabase/migrations/20260724030000_full_menu_catalog.sql
--
-- Ports the full real menu (src/data/menu.ts, 47 items transcribed from the
-- printed menu) into the operational database, across every branch, so the
-- ordering system (/order) is complete before going live. Replaces the
-- earlier ~10-item test subset (Rubaga only) that just proved the ordering
-- pipeline worked. Categories are shared (branch_id null) since every
-- branch serves the identical catalog today; items are per-branch (schema
-- requires it, and it's the correct model if a branch's stock/pricing ever
-- diverges later). The public marketing /menu page is untouched by this —
-- it stays static, per the explicit decision to keep the two menus separate.

-- Remove the earlier Rubaga-only test subset (4 branch-scoped categories +
-- their items) — being replaced by the full shared-category catalog below.
-- Safe: order_items.menu_item_id is ON DELETE SET NULL, so historical
-- orders keep their name_snapshot regardless.
delete from public.menu_items where category_id in (
  'a0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000002',
  'a0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000004'
);
delete from public.menu_categories where id in (
  'a0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000002',
  'a0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000004'
);


